import re
from itertools import combinations
from math import comb
from random import Random


MAX_COUNT = 293930
REFERENCE_LIMIT = 100000


def _bounded_int(token: str, low: int, high: int) -> int | None:
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    negative = token.startswith("-")
    digits = token.lstrip("+-").lstrip("0") or "0"
    if len(digits) > len(str(high)):
        return None
    value = int(digits)
    if negative:
        value = -value
    return value if low <= value <= high else None


def _parse_input(inp: str) -> tuple[int, int] | None:
    tokens = inp.split()
    if len(tokens) != 2:
        return None
    length = _bounded_int(tokens[0], 2, 12)
    if length is None:
        return None
    maximum = _bounded_int(tokens[1], 10 * length - 9, 10 * length)
    if maximum is None:
        return None
    return length, maximum


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        (2, 11),
        (2, 20),
        (3, 23),
        (4, 31),
        (4, 40),
        (2, 12),
        (3, 30),
        (4, 32),
    ]
    result = []
    for index in range(n):
        if index < len(cases):
            length, maximum = cases[index]
        else:
            length = rng.randint(2, 4)
            maximum = rng.randint(10 * length - 9, 10 * length)
        result.append(f"{length} {maximum}\n")
    return result


def gen_stress(seed: int) -> list[str]:
    return ["12 120\n", "11 110\n"]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse_input(inp)
    if parsed is None:
        return [("POST-1", "Input is outside the specified domain.")]
    length, maximum = parsed

    lines = out.splitlines()
    if not lines:
        return [("POST-2", "Missing count line.")]
    header = lines[0].split()
    if len(header) != 1:
        return [("POST-2", "The count line must contain one integer.")]
    count = _bounded_int(header[0], 1, MAX_COUNT)
    if count is None:
        return [("POST-2", "The count must be an integer in [1, 293930].")]
    if len(lines) != count + 1:
        return [("POST-2", "The number of sequence lines differs from the count.")]

    first = None
    previous = None
    for line_number in range(1, len(lines)):
        tokens = lines[line_number].split()
        if len(tokens) != length:
            return [("POST-2", f"Line {line_number + 1} must contain {length} integers.")]

        values = []
        for token in tokens:
            if re.fullmatch(r"[+-]?[0-9]+", token) is None:
                return [("POST-2", f"Line {line_number + 1} contains a non-integer token.")]
            value = _bounded_int(token, 1, maximum)
            if value is None:
                return [("POST-3", f"Line {line_number + 1} has a value outside [1, {maximum}].")]
            values.append(value)
        row = tuple(values)

        if any(right - left < 10 for left, right in zip(row, row[1:])):
            return [("POST-3", f"Line {line_number + 1} has an adjacent gap below 10.")]
        if previous is not None and row <= previous:
            return [("POST-4", f"Line {line_number + 1} does not strictly follow the previous sequence.")]
        if first is None:
            first = row
        previous = row

    smallest = tuple(1 + 10 * index for index in range(length))
    largest = tuple(maximum - 10 * index for index in range(length - 1, -1, -1))
    if first != smallest or previous != largest:
        return [("POST-5", "The first or last valid sequence is missing.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for _ in range(n):
        length = rng.randint(2, 12)
        maximum = rng.randint(10 * length - 9, 10 * length)
        spaces = " " * rng.randint(2, 6)
        original = f"{length} {maximum}\n"
        reformatted = f"{length}{spaces}{maximum}\n"
        pairs.append(("POST-1", "equal", original, reformatted))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse_input(inp)
    if parsed is None:
        return None
    length, maximum = parsed
    if comb(maximum, length) > REFERENCE_LIMIT:
        return None

    rows = []
    for row in combinations(range(1, maximum + 1), length):
        if all(left + 10 <= right for left, right in zip(row, row[1:])):
            rows.append(" ".join(map(str, row)))
    return "\n".join([str(len(rows)), *rows]) + "\n"
